import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class PublicExamplesTest{@Test void publishedTwoTwoOneOneAndSharedBook(){var first=new course.examples.objects.Book("First");Object owner=TaskBinding.owner(new ArrayList<>(List.of(first)));var view=TaskBinding.view(owner);var copy=TaskBinding.copy(owner);var snapshot=TaskBinding.snapshot(owner);TaskBinding.add(owner,new course.examples.objects.Book("Second"));assertEquals(2,TaskBinding.view(owner).size());assertEquals(2,view.size());assertEquals(1,copy.size());assertEquals(1,snapshot.size());first.borrow();for(var list:List.of(view,copy,snapshot))assertTrue(list.get(0).borrowed());assertThrows(UnsupportedOperationException.class,()->view.add(first));assertThrows(UnsupportedOperationException.class,()->snapshot.add(first));}}
